# Generated by manage.py generate_test_cases.
from datetime import date, time
from typing import Any

from django.core.exceptions import ValidationError

from bloomerp.communication.calendar.booking_availability import BookingLinkAvailability
from bloomerp.form_fields.booking_availability_field import BookingAvailabilityField
from bloomerp.tests.base import (
    BloomerpFormFieldTestCase,
    FormFieldScenario,
    ExpectedFormFieldException,
)


class TestBookingAvailabilityFieldFormField(BloomerpFormFieldTestCase):
    field_class = BookingAvailabilityField

    def get_test_scenarios(self) -> list[FormFieldScenario[BookingAvailabilityField]]:
        """Exercise the schedule JSON contract, local hours and validation errors."""
        invalid = [ExpectedFormFieldException(phase="clean", exception=ValidationError)]
        return [
            FormFieldScenario(
                name="Round trip bounded dates and local availability",
                clean_value={
                    "start_date": "2026-11-28",
                    "end_date": "2026-12-08",
                    "days": {"monday": [{"start": "13:00", "end": "17:00"}, {"start": "09:00", "end": "12:00"}]},
                    "exceptions": [
                        {"date": "2026-11-30", "hours": []},
                        {"date": "2026-12-01", "hours": [{"start": "10:30", "end": "12:00"}]},
                    ],
                },
                clean_result_validators=self.applies_date_overrides,
            ),
            FormFieldScenario(
                name="Read an existing flat weekday schedule",
                clean_value='{"friday":[{"start":"08:30:00","end":"12:00"}]}',
                clean_result_validators=self.normalizes_weekdays,
            ),
            FormFieldScenario(
                name="Reject overlapping weekly hours",
                clean_value={"days": {"monday": [{"start": "09:00", "end": "13:00"}, {"start": "12:00", "end": "17:00"}]}},
                expected_exceptions=invalid,
            ),
            FormFieldScenario(
                name="Reject reversed availability dates",
                clean_value={"start_date": "2026-11-30", "end_date": "2026-11-29"},
                expected_exceptions=invalid,
            ),
            FormFieldScenario(
                name="Reject duplicate date overrides",
                clean_value={"exceptions": [{"date": "2026-11-30"}, {"date": "2026-11-30"}]},
                expected_exceptions=invalid,
            ),
        ]

    def applies_date_overrides(self, value: Any) -> bool:
        """Verify overrides, chronological recurring hours, and inclusive bounds."""
        schedule = BookingLinkAvailability.model_validate(value)
        return (
            value["days"]["monday"][0]["start"] == "09:00"
            and schedule.hours_on(date(2026, 11, 23)) == []
            and schedule.hours_on(date(2026, 11, 30)) == []
            and schedule.hours_on(date(2026, 12, 1))[0].start == time(10, 30)
            and len(schedule.hours_on(date(2026, 12, 7))) == 2
            and schedule.hours_on(date(2026, 12, 14)) == []
        )

    def normalizes_weekdays(self, value: Any) -> bool:
        """Preserve hours while serializing them in the new day mapping."""
        return value == {"days": {"friday": [{"start": "08:30", "end": "12:00"}]}}
